package com.muoniumplayer.configskija.library;

import com.google.gson.*;
import com.muoniumplayer.configskija.host.library.OldMusicLoader;
import com.muoniumplayer.core.preset.codec.PresetLimits;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/** Synthetic old-run fixtures only; verifies source bytes do not change and secrets never reach output. */
public final class OldMusicLoaderTest {
    private static int checks,skips;
    private static final String SECRET="fixture-cookie-NEVER-COPY-59d1";
    private static void check(boolean value,String reason){checks++;if(!value)throw new AssertionError(reason);}
    public static void main(String[] args)throws Exception{
        Path root=Path.of(args.length==0?"build/library-host-data":args[0]);Files.createDirectories(root);Path run=Files.createTempDirectory(root,"old-music-loader-");
        String baseline=baseline();OldMusicLoader loader=new OldMusicLoader(baseline);boolean schemaRejected=false;try{JsonObject untrusted=new JsonObject();untrusted.add("accounts",new JsonObject());new OldMusicLoader(envelope(untrusted));}catch(IllegalArgumentException expected){schemaRejected=true;}check(schemaRejected,"current schema cannot expand allowlist beyond the nine verified music domains");projection(run,loader);fallbacks(run,loader,baseline);rejections(run,loader);links(run,loader);arraysAndNumbers(run,loader);
        System.out.println("OldMusicLoaderTest: "+checks+" checks passed; symlink capability skips="+skips);
    }
    private static String baseline(){
        JsonObject state=new JsonObject();for(String id:new TreeSet<>(OldMusicLoader.DOMAIN_IDS))state.add(id,new JsonObject());
        state.add("hud",JsonParser.parseString("{\"enabled\":true,\"scale\":1.0,\"title\":\"current\",\"nested\":{\"strength\":0.5},\"bands\":[0,1],\"objects\":[{\"gain\":0}],\"empty\":[],\"untyped\":null}").getAsJsonObject());state.getAsJsonObject("theme").addProperty("name","current");state.getAsJsonObject("foliaBg").addProperty("enabled",true);return envelope(state);
    }
    private static String envelope(JsonObject state){JsonObject o=new JsonObject();o.addProperty("format","muonium.profile.music");o.addProperty("version",1);o.addProperty("localOnly",true);o.add("state",state);return o.toString();}
    private static Path file(Path run,String name)throws IOException{Path file=run.resolve("profiles").resolve(name).resolve(OldMusicLoader.FILE_NAME);Files.createDirectories(file.getParent());return file;}
    private static void projection(Path run,OldMusicLoader loader)throws Exception{
        JsonObject state=JsonParser.parseString("{\"hud\":{\"enabled\":false,\"scale\":1.7,\"title\":\"legacy\",\"nested\":{\"strength\":0.9,\"cookie\":\""+SECRET+"\"},\"bands\":[4,\"bad-type\"],\"objects\":[{\"gain\":3,\"cookie\":\""+SECRET+"\"}],\"empty\":[{\"cookie\":\""+SECRET+"\"}],\"untyped\":{\"cookie\":\""+SECRET+"\"},\"cookie\":\""+SECRET+"\"},\"theme\":{\"name\":false},\"foliaBg\":{\"enabled\":false},\"foliabg\":{\"cookie\":\""+SECRET+"\"},\"accounts\":{\"cookie\":\""+SECRET+"\"},\"provider\":{\"token\":\""+SECRET+"\"}}").getAsJsonObject();
        JsonObject source=JsonParser.parseString(envelope(state)).getAsJsonObject();source.addProperty("cookie",SECRET);Path file=file(run,"Night");Files.writeString(file,source.toString());byte[] before=Files.readAllBytes(file);var modified=Files.getLastModifiedTime(file);
        OldMusicLoader.Result result=loader.load(run,"Night");JsonObject clean=JsonParser.parseString(result.envelope()).getAsJsonObject(),hud=clean.getAsJsonObject("state").getAsJsonObject("hud");
        check(result.origin()==OldMusicLoader.Origin.LEGACY_SCHEMA_FILTERED&&result.copiedKeys()>0,"valid named envelope uses old schema-compatible values");check(!hud.get("enabled").getAsBoolean()&&hud.get("scale").getAsDouble()==1.7&&hud.get("title").getAsString().equals("legacy"),"primitive booleans/numbers/strings migrate without coercion");check(hud.getAsJsonObject("nested").get("strength").getAsDouble()==.9,"nested known key migrated");check(!hud.has("cookie")&&!hud.getAsJsonObject("nested").has("cookie"),"cookie removed at both known-domain levels");check(!hud.getAsJsonArray("objects").get(0).getAsJsonObject().has("cookie"),"object-array unknown cookie removed");check(hud.getAsJsonArray("objects").get(0).getAsJsonObject().get("gain").getAsInt()==3,"object array known value migrated");check(hud.getAsJsonArray("bands").get(0).getAsInt()==4&&hud.getAsJsonArray("bands").get(1).getAsInt()==1,"array mismatch preserves the corresponding baseline slot");check(hud.getAsJsonArray("empty").isEmpty()&&hud.get("untyped").isJsonNull(),"unproven empty-array/null types are not guessed");check(clean.getAsJsonObject("state").getAsJsonObject("theme").get("name").getAsString().equals("current"),"type mismatch keeps current schema value");check(!clean.getAsJsonObject("state").getAsJsonObject("foliaBg").get("enabled").getAsBoolean()&&!clean.getAsJsonObject("state").has("foliabg"),"foliaBg matches exact real case");check(clean.getAsJsonObject("state").keySet().equals(OldMusicLoader.DOMAIN_IDS),"only nine real current domains in result");check(!result.envelope().contains(SECRET)&&!result.diagnostics().toString().contains(SECRET)&&!result.toString().contains(SECRET),"unknown auth/cookie values never reach payload or diagnostics");check(result.diagnostics().stream().anyMatch(d->d.code().equals("unknown-music-domain"))&&result.diagnostics().stream().anyMatch(d->d.code().equals("unknown-music-key"))&&result.diagnostics().stream().anyMatch(d->d.code().equals("music-type-mismatch")),"unknown domains/keys and type mismatches diagnosed");check(Arrays.equals(before,Files.readAllBytes(file))&&modified.equals(Files.getLastModifiedTime(file)),"read-only loader leaves source bytes and mtime unchanged");
    }
    private static void fallbacks(Path run,OldMusicLoader loader,String baseline)throws Exception{
        Files.createDirectories(run.resolve("config"));Files.writeString(run.resolve("config").resolve(OldMusicLoader.FILE_NAME),SECRET);
        OldMusicLoader.Result root=loader.load(run,"");check(root.origin()==OldMusicLoader.Origin.CURRENT_ROOT_BASELINE&&root.copiedKeys()==0,"root never reads a local envelope file");check(root.envelope().equals(OldMusicLoader.envelope(baseline).toString()),"root retains exact current capture baseline");OldMusicLoader.Result missing=loader.load(run,"Missing");check(missing.origin()==OldMusicLoader.Origin.CURRENT_MISSING_BASELINE&&missing.diagnostics().stream().anyMatch(d->d.code().equals("missing-legacy-music-envelope")),"missing named envelope explicit baseline fallback");
        JsonObject unknown=new JsonObject();unknown.add("hud",new JsonObject());Path empty=file(run,"Empty");Files.writeString(empty,envelope(unknown));OldMusicLoader.Result zero=loader.load(run,"Empty");check(zero.copiedKeys()==0&&zero.diagnostics().stream().anyMatch(d->d.code().equals("no-compatible-music-keys")),"zero compatible fields not called music restoration");
    }
    private static void rejected(OldMusicLoader loader,Path run,String name,String code)throws Exception{try{loader.load(run,name);throw new AssertionError("expected rejection: "+name);}catch(OldMusicLoader.Rejected failure){check(failure.diagnostics().stream().anyMatch(d->d.code().equals(code)),"explicit rejection code "+code);check(!failure.toString().contains(SECRET)&&!failure.diagnostics().toString().contains(SECRET),"rejected source does not leak body into diagnostics");}}
    private static void rejections(Path run,OldMusicLoader loader)throws Exception{
        Path file=file(run,"BadHeader");Files.writeString(file,"{\"format\":\"muonium.profile.music\",\"version\":1,\"localOnly\":false,\"state\":{}} ");rejected(loader,run,"BadHeader","invalid-legacy-music-envelope");
        for(String header:List.of("{\"format\":\"wrong\",\"version\":1,\"localOnly\":true,\"state\":{}}","{\"format\":\"muonium.profile.music\",\"version\":\"1\",\"localOnly\":true,\"state\":{}}","{\"format\":\"muonium.profile.music\",\"version\":1,\"localOnly\":1,\"state\":{}}","{\"format\":\"muonium.profile.music\",\"version\":1,\"localOnly\":true,\"state\":[]}")){Files.writeString(file,header);rejected(loader,run,"BadHeader","invalid-legacy-music-envelope");}
        Files.writeString(file,"not-json "+SECRET);rejected(loader,run,"BadHeader","invalid-legacy-music-envelope");Files.write(file,new byte[]{(byte)0xc3,0x28});rejected(loader,run,"BadHeader","invalid-legacy-music-encoding");
        Files.writeString(file," ".repeat(PresetLimits.MAX_JSON_CHARS+1));rejected(loader,run,"BadHeader","legacy-music-too-large");Files.write(file,new byte[(int)OldMusicLoader.MAX_FILE_BYTES+1]);rejected(loader,run,"BadHeader","legacy-music-too-large");Files.writeString(file,"[".repeat(PresetLimits.MAX_DEPTH+1)+"0"+"]".repeat(PresetLimits.MAX_DEPTH+1));rejected(loader,run,"BadHeader","legacy-music-too-deep");
        for(String name:List.of("../outside","Night/../../outside","..",".","C:outside","Night\\outside","Night "))rejected(loader,run,name,"invalid-legacy-music-path");
        Path dir=file(run,"Directory");Files.createDirectory(dir);rejected(loader,run,"Directory","unsafe-legacy-music-path");
    }
    private static void links(Path run,OldMusicLoader loader)throws Exception{
        Path target=file(run,"LinkTarget");Files.writeString(target,baseline());Path link=file(run,"FileLink");
        try{Files.createSymbolicLink(link,target);rejected(loader,run,"FileLink","unsafe-legacy-music-path");Path directory=run.resolve("profiles/DirLink");Files.createSymbolicLink(directory,target.getParent());rejected(loader,run,"DirLink","unsafe-legacy-music-path");}
        catch(UnsupportedOperationException|FileSystemException unavailable){skips++;System.out.println("OldMusicLoaderTest: symbolic-link fixtures unavailable on this filesystem; no passing claim for that fixture");}
    }
    private static void arraysAndNumbers(Path run,OldMusicLoader loader)throws Exception{
        JsonObject state=JsonParser.parseString("{\"hud\":{\"scale\":1e999,\"title\":\""+"x".repeat(PresetLimits.MAX_VALUE_STRING_CHARS+1)+"\",\"enabled\":\"false\"}}").getAsJsonObject();Path file=file(run,"Bounds");Files.writeString(file,envelope(state));OldMusicLoader.Result result=loader.load(run,"Bounds");JsonObject hud=JsonParser.parseString(result.envelope()).getAsJsonObject().getAsJsonObject("state").getAsJsonObject("hud");check(hud.get("scale").getAsDouble()==1&&hud.get("title").getAsString().length()==PresetLimits.MAX_VALUE_STRING_CHARS+1&&hud.get("enabled").getAsBoolean(),"nonfinite/string-boolean mismatches retain baseline while known LOCAL strings respect the full envelope bound");check(result.copiedKeys()==1,"only the valid known LOCAL string counts as migrated, rejected numbers/booleans do not");JsonObject expanding=new JsonObject(),data=new JsonObject();JsonArray many=new JsonArray();for(int i=0;i<2000;i++){JsonObject object=new JsonObject();object.addProperty("gain",i);object.addProperty("cookie",SECRET);many.add(object);}data.add("objects",many);expanding.add("hud",data);Files.writeString(file,envelope(expanding));OldMusicLoader.Result bounded=loader.load(run,"Bounds");check(JsonParser.parseString(bounded.envelope()).getAsJsonObject().getAsJsonObject("state").getAsJsonObject("hud").getAsJsonArray("objects").size()==1,"unknown array indexes cannot amplify current object schema");check(bounded.diagnostics().stream().anyMatch(d->d.code().equals("unknown-music-array-index")),"extra old array indexes explicitly diagnosed");
    }
}
